using namespace ofo;
void check(bool ok,const char*s){if(!ok)throw std::runtime_error(s);}
int main(int argc,char**argv){try{check(clean_path("DATA/Cars/Car_3/body.bgm")=="cars/car_3/body.bgm","case paths");bool denied=false;try{clean_path("../secret");}catch(...){denied=true;}check(denied,"traversal rejected");auto n=parse_bed("# comment\nCar.X={ Mass=3, V={1,-2,3}, T={A=4}, Ref=Car.Y,};");check(n["Car.X"]["Mass"]==3&&n["Car.X"]["V"]["2"]==-2,"BED numeric tree");
auto temp=fs::temp_directory_path()/"openfo-parser-tests";fs::create_directories(temp);{std::ofstream f(temp/"short.bgm",std::ios::binary);f.write("\x04\x00\x01\x00",4);}bool malformed=false;try{Resources r(temp);load_geometry(r,"short.bgm");}catch(const std::exception&){malformed=true;}check(malformed,"truncated geometry rejected");{std::ofstream f(temp/"bad.bgm",std::ios::binary);uint32_t header[]={0x10004,0xffffffff};f.write((const char*)header,sizeof header);}malformed=false;try{Resources r(temp);load_geometry(r,"bad.bgm");}catch(const std::exception&){malformed=true;}check(malformed,"excessive record count rejected");fs::remove_all(temp);
 auto unicode=fs::temp_directory_path()/fs::u8path(u8"OpenFO-ресурси-ї");fs::create_directories(unicode/"cars");{std::ofstream f(unicode/"cars"/fs::u8path(u8"файл.bin"),std::ios::binary);f<<"native-bytes";}Resources ur(unicode);auto ub=ur.read(u8"DATA/CARS/файл.bin");check(std::string(ub.begin(),ub.end())=="native-bytes","Unicode resource root");fs::remove_all(unicode);
 if(argc>1){Resources r(argv[1]);auto c=load_vehicle(r,3,argc>2?argv[2]:"");check(c.mass>700&&c.mass<1100,"physical mass");check(c.mass==870&&std::abs(c.inertia.x-1021.38f)<.01f,"Pepper native configuration");auto bullet=load_vehicle(r,15,argc>2?argv[2]:"");check(bullet.mass==1789&&std::abs(bullet.inertia.x-3544.009f)<.01f,"Bullet native configuration");check(c.inertia.x>700&&c.wheels[0].radius>.2,"native dimensions");auto g=load_geometry(r,c.body);check(g.triangles>1000&&g.materials.size()>2,"real car geometry");for(auto&m:g.meshes){check(lower(m.name).find("shadow")==std::string::npos,"car shadow removed");for(auto i:m.indices)check(i<m.vertices.size(),"indices bounded");}auto t=load_geometry(r,"data/tracks/forest/forest1/geometry/track_geom.w32");check(t.triangles>60000,"no 60k polygon cap");check(length(point(load_spawn(r,"data/tracks/forest/forest1/a"),{}))>50,"authored spawn");std::cout<<"car triangles="<<g.triangles<<" track="<<t.triangles<<" mass="<<c.mass<<"\n";}
 std::cout<<"core passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
